import { NextResponse } from 'next/server';

export const dynamic = 'force-dynamic';

/** Current backend time (display only). Official clock-in / clock-out times are generated by those APIs themselves. */
export async function GET() {
    return NextResponse.json(
        { success: true, serverTime: new Date().toISOString(), timezone: 'Asia/Kolkata' },
        { headers: { 'Cache-Control': 'no-store' } }
    );
}